-- ============================================================================
-- FC4: Gas Processing joins the catalog, the FOURTH Facilities course.
--
-- Catalog row (module 'facilities'; path_order 42, directly above FC3 rotating
-- at 41, FC2 linesizing at 40 and FC1 separation at 39; prereq_slug NULL, the
-- carried-over answer "no hard prerequisite inside a module") plus the three
-- capstones and their eighteen graded fields, generated by
-- tools/course-waves/gasprocessing/gen_course.py from fields.json,
-- precision.json and the capstone constants in fc4_fields_capstone.mjs. Deep
-- seeds are three separate migrations; the go-live is a fifth and is HELD until
-- a NextGen production upload carries the route /dashboard/apps/gasprocessing,
-- because the 78 lessons, the teaching lab (gasprocessingLab.js) and its three
-- explorer panels ship in the zip and not in this database.
--
-- THE ONE SENTENCE THE COURSE IS. Gas conditioning is three separate balances
-- over one stream, and the discipline is knowing which of the numbers in front
-- of you the engine COMPUTED, which one you CHOSE, and which one it simply kept
-- to itself.
--
-- THE ENGINE. engines/facilities/gasProcessing.js (the saturation fit and the
-- band it stands behind, the water balance, the glycol circulation, the
-- reboiler duty split into named parts, the still overhead, the Kremser
-- absorber, the amine mole balance and its loading swing, the contactor, the
-- compressibility and its temperature derivative, the Joule-Thomson
-- coefficient and the marched let-down) over engines/production/gasProperties.js
-- and engines/facilities/separatorSizing.js, which is where the repaired module
-- takes its DAK validity band from. Vendored at engines 82ec6d4, the FC4-0
-- repair wave, sha-identical over ten paths.
--
-- THE MODULE'S RETURN CONTRACT, which the Associate tier grades a reading of.
-- Nine exports are DOORS: each takes a named-argument object, answers with an
-- object, and puts a named string on an `error` key when it cannot answer. Four
-- are SCALAR HELPERS: each takes one positional value, answers with a bare
-- number or one row of a table, and reports no answer with a bare NaN or a
-- null. Every helper is consumed by a door, so no helper's no-answer reaches a
-- caller of a door. This module throws nothing at all.
--
-- NOTHING GRADED DEPENDS ON A HELD-FOR-LITERATURE QUANTITY, and each one is
-- neutralised by construction rather than by hope. The McKetta and Wehe
-- real-gas correction is held, so IKOT ABASI sits BELOW the pressure at which
-- the engine warns and ESCRAVOS lets down from below it too. The water overhead
-- the reboiler pays for is a typed constant with no source, so no graded
-- Associate field reads a reboiler duty and the SENSIBLE half, built entirely
-- from stated inputs, is what is graded. The amine contactor's liquid density
-- is the wrong fluid for an amine, so no graded Professional field reads a
-- contactor diameter. The customary amine duty per gallon is held, so OTUMARA
-- states its own 920 Btu a gallon. The BTEX absorbed fraction and molecular
-- weight are operating values, so both are stated wherever a BTEX figure is
-- graded. The go-live asserts all five, on the labels and again on the values.
--
-- THE CAPSTONE GRADES WHAT THE COURSE TEACHES A READER TO GET RIGHT: that a
-- water content is intensive and a water rate is not, that a circulation ratio
-- is a choice the engine refuses to make, that a contactor is a staged device
-- with a ceiling no steel can buy past, that a glycol circulation and an amine
-- circulation carry the same unit and answer different questions, and that a
-- coefficient at the inlet applied across a whole let-down is not the drop.
-- All eighteen graded values were swept against every number the digest prints
-- and against every number handed to a learner in a prompt, at each field's own
-- tolerance: 0 collisions, and 0 pairwise.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('gasprocessing', 'Gas Processing', 'facilities', 42, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'gasprocessing', 'beginner', 'associate',
  'IKOT ABASI, a TEG dehydration train read from the line conditions to the still overhead',
  'One stream, one balance, end to end',
  'IKOT ABASI, the TEG dehydration train on a gas gathering station making pipeline spec. The contactor takes 47 MMscfd at 880 psia and 109 degF and has to leave at 5 lb a MMscf. The circulation ratio chosen for this unit is 3.6 gallons of glycol per pound of water, and the lean glycol is 99.4 weight percent TEG. The absorber runs at 109 degF and the reboiler at 368 degF, with a reflux ratio of 0.22. The glycol has a heat capacity of 0.55 Btu per lb degF and weighs 9.3 lb a gallon, both stated, so they are conditions of the problem rather than lookups. The inlet carries 155 ppmv of BTEX, of which 0.12 is absorbed, at a molecular weight of 92. Report six values: the water the gas carries at the inlet, the water the unit takes out, the glycol circulation as a rate and as a daily volume, the sensible heat a gallon of that glycol costs, and the BTEX that reaches the still overhead. Water contents in lb a MMscf, circulations in gpm and BTEX in short tons a year, to six decimals. Daily masses in lb a day, daily volumes in gallons a day and heat in Btu a gallon, to four decimals.',
  jsonb_build_array(
    jsonb_build_object('key','inletLbMMscf', 'label','Saturated water content of the gas at the contactor inlet', 'unit','lb/MMscf', 'expected',66.84513037385786, 'tol',0.0001),
    jsonb_build_object('key','waterLbDay', 'label','Water the unit takes out, the content difference applied to the rate', 'unit','lb/day', 'expected',2906.7211275713194, 'tol',0.01),
    jsonb_build_object('key','circGpm', 'label','Glycol circulation, the stated ratio applied to that water rate', 'unit','gpm', 'expected',7.266802818928299, 'tol',1e-05),
    jsonb_build_object('key','circGpd', 'label','The same glycol circulation as a daily volume', 'unit','gal/day', 'expected',10464.19605925675, 'tol',0.01),
    jsonb_build_object('key','sensiblePerGal', 'label','Sensible heat per gallon circulated, built from the stated glycol properties', 'unit','Btu/gal', 'expected',1324.7850000000003, 'tol',0.0001),
    jsonb_build_object('key','btexTonsYear', 'label','BTEX carried to the still overhead', 'unit','short tons/yr', 'expected',38.678401618815194, 'tol',1e-05)
  )
),
(
  'gasprocessing', 'intermediate', 'professional',
  'OTUMARA, a sour gas train read as a staged device and then as a mole balance',
  'The column, the solvent, and which question each number answers',
  'OTUMARA, the sour gas train. The absorber''s own working point is an absorption factor of 1.85 over 5 stages, and the contract spec demands a removal of 0.94 of that same absorber. The amine unit takes 71 MMscfd carrying 6.4 mol percent CO2 and 0.78 mol percent H2S and has to leave at 2.5 and 0.0004. The solvent is DEA at 33 weight percent, circulating from a lean loading of 0.07 to a rich loading of 0.38. The regenerator is run at 920 Btu a gallon, stated rather than taken from any table. A retune would take the lean loading to 0.03 and leave every other condition where it is. Report six values: what the absorber removes at its stated working point, the stages the contract removal demands of it, the acid gas the solution picks up as moles, the amine circulation, the regenerator duty on that circulation, and the circulation again after the retune. Removals as a fraction, stages, circulations in gpm and the duty in MMBtu an hour, to six decimals. Moles in lbmol a day, to four decimals.',
  jsonb_build_array(
    jsonb_build_object('key','fractionRemoved', 'label','Fraction removed by the absorber at its stated working point', 'unit','fraction', 'expected',0.9782550162942297, 'tol',5e-07),
    jsonb_build_object('key','stagesNeeded', 'label','Stages the contract removal demands at that same absorption factor', 'unit','stages', 'expected',3.4199666970606337, 'tol',1e-06),
    jsonb_build_object('key','acidMolesDay', 'label','Acid gas the solution picks up, as moles', 'unit','lbmol/day', 'expected',8755.36188232743, 'tol',0.01),
    jsonb_build_object('key','circGpm', 'label','Amine circulation, from the mole balance closed by the loading swing', 'unit','gpm', 'expected',734.5776758597356, 'tol',1e-05),
    jsonb_build_object('key','reboilerMMBtuHr', 'label','Regenerator duty on that circulation, at the stated duty per gallon', 'unit','MMBtu/hr', 'expected',40.54868770745741, 'tol',1e-05),
    jsonb_build_object('key','circGpmRetuned', 'label','Amine circulation again with the regenerator retuned to a leaner lean', 'unit','gpm', 'expected',650.6259414757658, 'tol',1e-05)
  )
),
(
  'gasprocessing', 'advanced', 'expert',
  'ESCRAVOS, a dew point skid from the compressibility derivative to the water left in the gas',
  'The cold end, marched rather than stepped',
  'ESCRAVOS, the dew point skid. Gas at 935 psia and 87 degF lets down across a choke to 405 psia into a low temperature separator. The gas gravity is 0.67 and its molar heat capacity is 10.2 Btu per lbmol degF. The let-down begins below the pressure at which this engine warns that its water chart correction is out of its stated band, so nothing reported here leans on a quantity held for the literature. Report six values: the compressibility temperature derivative at the inlet, the Joule-Thomson coefficient there, the cooling the let-down produces, the temperature the gas reaches, and the water it carries at the inlet and can still hold at the cold spot. The derivative per degR, the coefficient in degF a psi, temperatures in degF and water contents in lb a MMscf, all to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','dzdT', 'label','Compressibility temperature derivative at the skid inlet', 'unit','per degR', 'expected',0.0009683744638956019, 'tol',5e-07),
    jsonb_build_object('key','muFPerPsi', 'label','Joule-Thomson coefficient at that inlet', 'unit','degF/psi', 'expected',0.06026080453221084, 'tol',5e-07),
    jsonb_build_object('key','dropF', 'label','Cooling across the let-down, marched rather than taken in one step', 'unit','degF', 'expected',33.72690128392314, 'tol',0.0001),
    jsonb_build_object('key','t2F', 'label','Temperature the gas reaches at the separator inlet', 'unit','degF', 'expected',53.27309871607686, 'tol',0.0001),
    jsonb_build_object('key','waterInLbMMscf', 'label','Water the gas carries at the skid inlet', 'unit','lb/MMscf', 'expected',32.20884788270555, 'tol',0.0001),
    jsonb_build_object('key','waterOutLbMMscf', 'label','Water the gas can still hold at the cold spot', 'unit','lb/MMscf', 'expected',23.519449233233914, 'tol',0.0001)
  )
)
on conflict (app_slug, tier) do nothing;
